// A greedy wildcard matcher. `*` stands for any run of characters.
export function matchGlob(pattern, path) {
  let p = 0;
  let s = 0;
  let star = -1;
  let mark = 0;

  while (s < path.length) {
    if (p < pattern.length && (pattern[p] === '?' || pattern[p] === path[s])) {
      p += 1;
      s += 1;
      continue;
    }
    if (p < pattern.length && pattern[p] === '*') {
      star = p;
      mark = s;
      p += 1;
      continue;
    }
    if (star !== -1) {
      p = star + 1;
      mark += 1;
      s = mark;
      continue;
    }
    return false;
  }

  while (p < pattern.length && pattern[p] === '*') p += 1;
  return p === pattern.length;
}
